# -*- coding: utf-8 -*-
# 第 11 批（B3）：高壓氣體勞工安全規則（111/9/14）第108條～第178條 補題
HG = "OSH-41"
Q = [
(HG,"第108條",2,"高壓氣體-供應",
 "供應冷媒氣體時，其設備應符合何項要求？",
 ["不得有腐蝕、裂隙、裂痕、皺紋等致減弱其強度，且應無漏洩冷媒氣體","不得有振動、噪音、異味等致影響其運轉，且應無超過設計溫度之情形","不得有塗裝剝落、標示不清等致難以辨識，且應無超過有效期限之情形","不得有超過內容積百分之九十之灌裝量，且應無未設液面計之承液器"],"a",
 "第108條：供應冷媒氣體時，其設備不得有腐蝕、裂隙、裂痕、皺紋等致減弱其強度，且無漏洩冷媒氣體者。第106條對高壓氣體灌氣容器等亦有相同要求；第206條並定冷凍機器之冷媒設備應具有可防止振動、衝擊、腐蝕等致使冷媒氣體外洩者。",
 "What condition must equipment meet when supplying refrigerant gas?",
 ["No corrosion, cracks, fissures or wrinkles weakening its strength, and no refrigerant leakage","No vibration, noise or odour affecting its operation, and no exceeding of the design temperature","No peeling paint or unclear marking making it hard to identify, and no expiry of the valid period","No filling above ninety percent of internal volume, and no receiver lacking a liquid level gauge"],
 "Article 108; compare Articles 106 and 206."),

(HG,"第110條",3,"高壓氣體-供應",
 "供應事業單位（不含液化石油氣及冷凍用高壓氣體者）之供應設施，其容器放置場、儲槽及導管各準用何規定？",
 ["容器以配管連接者準用容器儲存及儲存場規定，其他者準用容器放置場規定；儲槽及導管另有準用","容器一律準用固定於車輛容器之運輸規定；儲槽準用防液堤規定；導管準用冷媒設備試驗之規定","容器一律準用加氣站灌裝之規定；儲槽準用埋設於地盤內之規定；導管準用二重管構造之規定","容器一律準用霧劑製造之規定；儲槽準用耐震構造之規定；導管準用毒性氣體除毒設備之規定"],"a",
 "第110條：供應事業單位之供應設施除依第104條、第106條、第107條、第109條（不含第六款、第八款）外，容器以配管連接者其容器放置場及灌氣容器等準用第116條及第121條第一款，其他者準用第79條；儲槽準用第113條及第119條；導管準用第80條之規定。",
 "For a supply enterprise, which rules apply to cylinder yards, storage tanks and pipelines?",
 ["Pipe-connected cylinders follow container storage and yard rules, others the cylinder yard rules; tanks and pipelines separately","All cylinders follow the rules for containers fixed on vehicles; tanks follow dike rules; pipelines follow refrigerant test rules","All cylinders follow the gas filling station rules; tanks follow the rules on burial in the ground; pipelines follow double-pipe rules","All cylinders follow the aerosol manufacturing rules; tanks follow earthquake-resistant rules; pipelines follow detox equipment rules"],
 "Article 110 lists the provisions applied by reference."),

(HG,"第111條",1,"高壓氣體-液化石油氣",
 "液化石油氣之容器放置場及灌氣容器等，其設置準用何規定？",
 ["準用容器放置場之警戒標示、輕質屋頂、不滯留構造、滅火設備及溫度四十度以下等規定","準用固定於車輛容器之防波板、高度檢知桿、工作箱距離及液面計材質等相關規定","準用毒性氣體製造設施之防毒措施、二重管構造及毒性危害標示等相關之各項規定","準用冷凍設備之壓縮機設置限制、冷媒設備耐壓氣密試驗及承液器液面計等規定"],"a",
 "第111條：液化石油氣容器放置場及灌氣容器等，準用第79條之規定。第79條要求容器放置場明確標示並設警戒標示、輕質屋頂、可燃性氣體漏洩不滯留構造、除毒設備、滅火設備、灌氣與殘氣容器分別放置、四周二公尺內禁煙火、溫度保持攝氏四十度以下、防翻倒掉落措施及不得攜入火源機具等。",
 "Which rules apply by reference to LPG cylinder yards and filled cylinders?",
 ["The cylinder yard rules on warning signs, light roofs, non-accumulating structure, extinguishers and 40 C limit","The rules for vehicle-mounted containers on baffles, height detectors, tool box distances and level gauge materials","The rules for toxic gas manufacturing on anti-poison measures, double-pipe construction and hazard marking","The refrigeration rules on compressor siting limits, refrigerant equipment testing and receiver level gauges"],
 "Article 111, applying Article 79."),

(HG,"第112條",2,"高壓氣體-液化石油氣",
 "以第二種供應設備供應液化石油氣時，其設置準用何規定？",
 ["準用消防設備、供應紀錄簿冊、容器狀態、消費設備確認、儲槽儲存及容器儲存等規定","準用加氣站承受灌裝車輛距離、拆卸連接部分及添加臭劑等相關之各項規定內容","準用毒性氣體之防毒措施、熔接接合、二重管構造及毒性危害標示等相關規定","準用冷凍機器容器之超音波探傷、放射線檢查及磁粉探傷試驗等相關之規定"],"a",
 "第112條：以第二種供應設備供應液化石油氣時，其設置準用第67條、第105條至第107條、第109條、第113條、第116條、第120條、第122條之規定，即消防設備、消費事業單位安全狀況紀錄簿冊、容器不得腐蝕裂痕、壓縮天然氣有效期限、消費設備之確認事項、以儲槽儲存、以容器儲存及液化石油氣儲存場等規定。第24條並定第二種供應設備為第一種以外者。",
 "Which rules apply by reference to supplying LPG with Class 2 supply equipment?",
 ["Fire equipment, supply record books, cylinder condition, consumer equipment checks, tank storage and container storage","Gas filling station rules on vehicle distance, disconnecting the loading equipment and adding odorant to the gas","Toxic gas rules on anti-poison measures, welded joints, double-pipe construction and toxicity hazard marking","Refrigeration container rules on ultrasonic testing, radiographic examination and magnetic particle testing"],
 "Article 112 lists the provisions applied by reference."),

(HG,"第114條",1,"高壓氣體-冷凍",
 "冷凍設備對於翻落、翻倒引起之衝擊，應如何處理？",
 ["應採取因翻落、翻倒等引起之衝擊之預防措施","應採取因振動、共振等引起之疲勞之檢測措施","應採取因腐蝕、劣化等引起之破裂之補強措施","應採取因高溫、低溫等引起之變形之絕熱措施"],"a",
 "第114條：冷凍設備應採取因翻落、翻倒等引起之衝擊之預防措施。第115條規定冷凍高壓氣體之儲存準用本條；第79條第十款對灌氣容器等（內容積五公升以下者除外）亦要求採取防止因翻倒、掉落引起衝擊及損傷附屬閥等之措施。",
 "What must be done about impact from falling or toppling of refrigeration equipment?",
 ["Measures preventing impact caused by falling or toppling over of the equipment","Measures detecting fatigue caused by vibration or resonance of the equipment","Measures reinforcing against rupture caused by corrosion or deterioration","Measures insulating against deformation caused by high or low temperature"],
 "Article 114; applied to storage by Article 115."),

(HG,"第115條",1,"高壓氣體-冷凍",
 "冷凍高壓氣體之儲存，準用何項規定？",
 ["準用冷凍設備應採取翻落翻倒衝擊預防措施之規定","準用儲槽儲存高壓氣體之通風良好與禁煙火規定","準用容器儲存氰化氫應每日檢點一次以上之規定","準用高壓氣體儲存場應設專用儲存場之相關規定"],"a",
 "第115條：冷凍高壓氣體之儲存，準用第114條之規定，即應採取因翻落、翻倒等引起之衝擊之預防措施。第243條規定第113條、第116條至第119條、第121條等儲存規定不適用於冷凍用高壓氣體，故冷凍高壓氣體之儲存僅準用第114條。",
 "Which rule applies by reference to the storage of refrigeration high-pressure gas?",
 ["The rule requiring measures preventing impact from falling or toppling over","The rule requiring good ventilation and no open flames for tank storage","The rule requiring daily checks of hydrogen cyanide containers in storage","The rule requiring a dedicated storage yard for high-pressure gas storage"],
 "Article 115, applying Article 114; see Article 243."),

(HG,"第117條",3,"高壓氣體-儲存",
 "儲槽或容器之容積在多少以下者，不受以儲槽及以容器儲存高壓氣體規定之限制？液化氣體如何換算容積？",
 ["容積在零點一五立方公尺以下者；液化氣體以質量十公斤換算為容積一立方公尺","容積在零點五立方公尺以下者；液化氣體以質量一百公斤換算為容積一立方公尺","容積在一點五立方公尺以下者；液化氣體以質量五公斤換算為容積一立方公尺","容積在零點零四立方公尺以下者；液化氣體以質量五十公斤換算為容積一立方公尺"],"a",
 "第117條：儲槽或容器之容積在零點一五立方公尺以下者，不受第113條及第116條規定之限制；高壓氣體為液化氣體時，前項之容積以質量十公斤換算為容積一立方公尺。第118條並定儲存容積在三百立方公尺或三千公斤以上之事業單位應設專用高壓氣體儲存場。",
 "Below what volume are tanks or containers exempt from the storage rules, and how is liquefied gas converted?",
 ["Volume of 0.15 cubic metre or less; liquefied gas converts 10 kg of mass to 1 cubic metre","Volume of 0.5 cubic metre or less; liquefied gas converts 100 kg of mass to 1 cubic metre","Volume of 1.5 cubic metres or less; liquefied gas converts 5 kg of mass to 1 cubic metre","Volume of 0.04 cubic metre or less; liquefied gas converts 50 kg of mass to 1 cubic metre"],
 "Article 117 sets the exemption threshold and the conversion."),

(HG,"第118條",2,"高壓氣體-儲存",
 "儲存高壓氣體之容積達多少之事業單位，應設專用之高壓氣體儲存場？",
 ["容積在三百立方公尺或三千公斤以上者；但甲類製造事業單位、供應事業單位經許可者除外","容積在一百立方公尺或一千公斤以上者；但乙類製造事業單位、消費事業單位經許可者除外","容積在一千立方公尺或一萬公斤以上者；但加氣站、第二種供應事業單位經許可者除外","容積在三十立方公尺或三百公斤以上者；但冷凍用製造事業單位、消費事業單位經許可者除外"],"a",
 "第118條：儲存高壓氣體之容積在三百立方公尺或三千公斤以上之事業單位應設專用儲存場（高壓氣體儲存場）；但甲類製造事業單位、供應事業單位經許可者，不在此限。第119條至第122條並分別規定以儲槽或容器儲存高壓氣體、液化石油氣之儲存場其設置準用之條文。",
 "Undertakings storing what volume of high-pressure gas must set up a dedicated storage yard?",
 ["300 cubic metres or 3,000 kg or more; Class A manufacturers and supply enterprises with permission are exempt","100 cubic metres or 1,000 kg or more; Class B manufacturers and consuming enterprises with permission are exempt","1,000 cubic metres or 10,000 kg or more; filling stations and Class 2 supply enterprises with permission are exempt","30 cubic metres or 300 kg or more; refrigeration manufacturers and consuming enterprises with permission are exempt"],
 "Article 118; Articles 119 to 122 detail the storage yards."),

(HG,"第119條",3,"高壓氣體-儲存",
 "以儲槽儲存高壓氣體之高壓氣體儲存場，下列何者屬其準用之規定？",
 ["境界警戒標示、儲槽間安全距離、防液堤、耐震構造、緊急遮斷裝置及漏洩警報等規定","加氣站承受灌裝車輛距離、拆卸連接部分後始得移動車輛及添加臭劑等相關規定","霧劑製造之四周二公尺限制、溫水試驗槽攝氏四十八度及倒轉台等相關之規定","冷凍機器容器之超音波探傷檢查、放射線檢查及磁粉探傷試驗合格等相關規定"],"a",
 "第119條：以儲槽儲存高壓氣體之高壓氣體儲存場，其設置準用第31條、第33條、第35條至第38條、第41條、第43條至第48條、第49條第一款及第二款、第50條至第53條及第60條、第62條至第69條之規定，包括境界警戒標示、與煙火設備八公尺距離、儲槽間距離、防液堤、耐震構造、緊急遮斷裝置及氣體漏洩檢知警報設備等。",
 "Which rules apply by reference to a high-pressure gas storage yard using storage tanks?",
 ["Boundary warning signs, tank separation distances, dikes, earthquake-resistant construction, shut-off devices and leak alarms","Gas filling station rules on vehicle distance, disconnecting before moving the vehicle and adding odorant to the gas","Aerosol manufacturing rules on the two-metre limit, the 48 degree water bath test and the container turning table","Refrigeration container rules on ultrasonic testing, radiographic examination and magnetic particle testing passes"],
 "Article 119 lists the provisions applied by reference."),

(HG,"第120條",3,"高壓氣體-液化石油氣",
 "以儲槽儲存液化石油氣之液化石油氣儲存場，下列何者屬其準用之規定？",
 ["儲槽耐熱構造或冷卻撒水設備、儲槽埋設於地盤內、儲槽室構造及防鏽措施等規定","毒性氣體之防毒措施、熔接接合、二重管構造及毒性危害標示等相關之各項規定","冷凍設備壓縮機設置限制、冷媒設備之氣密與耐壓試驗及承液器液面計等規定","固定於車輛容器之防波板、高度檢知桿、工作箱距離及液面計材質等相關規定"],"a",
 "第120條：以儲槽儲存液化石油氣之液化石油氣儲存場，其設置準用第31條、第33條、第35條至第39條、第41條、第43條至第46條、第48條至第53條、第57條、第60條、第66條至第69條及第81條至第83條之規定，其中第57條為儲槽耐熱構造或冷卻撒水設備、第81條至第83條為埋設於地盤內、儲槽室構造及防鏽措施。",
 "Which rules apply by reference to an LPG storage yard using storage tanks?",
 ["Heat-resistant tank construction or cooling sprinklers, burial in the ground, tank chamber construction and anti-rust treatment","Anti-poison measures for toxic gas, welded joints, double-pipe construction and toxicity hazard marking requirements","Siting limits for refrigeration compressors, airtightness and pressure testing of refrigerant units and receiver level gauges","Rules for vehicle-mounted containers on baffles, height detectors, tool box distances and level gauge material limits"],
 "Article 120 lists the provisions applied by reference."),

(HG,"第121條",3,"高壓氣體-儲存",
 "以容器儲存高壓氣體之高壓氣體儲存場，容器以配管連接者與未以配管連接者，其設置有何不同？",
 ["二者均準用容器放置場前五款規定；以配管連接者之配管另應準用耐壓氣密試驗及厚度規定","二者均準用容器放置場全部規定；以配管連接者之配管另應準用二重管構造及熔接接合規定","以配管連接者準用容器放置場前五款；未以配管連接者僅須準用滅火設備及禁煙火之規定","以配管連接者準用防液堤與耐震構造規定；未以配管連接者準用固定於車輛容器運輸規定"],"a",
 "第121條：以容器儲存高壓氣體之高壓氣體儲存場，容器以配管連接者，準用第79條第一款至第五款之規定；其可流通高壓氣體之配管者，且應準用第41條及第43條高壓氣體設備之規定。容器未以配管連接者，準用第79條第一款至第五款之規定。第122條對液化石油氣儲存場則另定不含第四款除毒設備。",
 "How do the rules differ for pipe-connected and unconnected containers in a high-pressure gas storage yard?",
 ["Both follow the first five cylinder yard rules; pipe-connected ones also follow the pressure test and thickness rules","Both follow all the cylinder yard rules; pipe-connected ones also follow double-pipe and welded joint requirements","Pipe-connected ones follow the first five cylinder yard rules; unconnected ones only need extinguishers and no flames","Pipe-connected ones follow dike and earthquake rules; unconnected ones follow the vehicle transport requirements"],
 "Article 121; compare Article 122 for LPG."),

(HG,"第122條",3,"高壓氣體-液化石油氣",
 "以容器儲存液化石油氣之液化石油氣儲存場，其準用之範圍為何？",
 ["以配管連接者準用容器放置場第一款至第五款（不含第四款）；未連接者準用第一款至第六款（不含第四款）","以配管連接者準用容器放置場第一款至第六款（不含第五款）；未連接者準用第一款至第五款（不含第五款）","以配管連接者準用容器放置場全部十一款規定；未連接者僅準用第一款至第三款之相關各項規定","以配管連接者準用容器放置場第六款至第十一款規定；未連接者準用第一款至第四款之相關規定"],"a",
 "第122條：以容器儲存液化石油氣之液化石油氣儲存場，容器以配管連接者準用第79條第一款至第五款（不含第四款）之規定；容器未以配管連接者準用第79條第一款至第六款（不含第四款）之規定。第79條第四款為二氧化硫、氨、氯等毒性氣體容器放置場之除毒設備，與液化石油氣無涉故予排除。",
 "What is the scope of provisions applied by reference to an LPG storage yard using containers?",
 ["Pipe-connected follow cylinder yard rules 1 to 5 excluding rule 4; unconnected follow rules 1 to 6 excluding rule 4","Pipe-connected follow cylinder yard rules 1 to 6 excluding rule 5; unconnected follow rules 1 to 5 excluding rule 5","Pipe-connected follow all eleven cylinder yard rules in full; unconnected follow only rules 1 to 3 of that article","Pipe-connected follow cylinder yard rules 6 to 11 only; unconnected follow rules 1 to 4 of that article instead"],
 "Article 122; rule 4 concerns detox equipment for toxic gases."),

(HG,"第123條、第128條、第129條、第135條、第136條、第137條、第138條、第139條、第140條、第141條",3,"高壓氣體-運輸",
 "固定於車輛運輸之容器，後方卸出式容器與其他容器對車輛後保險桿之水平距離各應保持多少？",
 ["後方卸出式容器之原閥及緊急遮斷閥四十公分以上；其他容器之後面三十公分以上","後方卸出式容器之原閥及緊急遮斷閥三十公分以上；其他容器之後面四十公分以上","後方卸出式容器之原閥及緊急遮斷閥二十公分以上；其他容器之後面五十公分以上","後方卸出式容器之原閥及緊急遮斷閥六十公分以上；其他容器之後面二十公分以上"],"a",
 "第128條：容器原閥置於容器後方之後方卸出式容器，應使容器原閥及緊急遮斷裝置之閥與車輛後保險桿後面間之水平距離保持在四十公分以上。第129條：後方卸出式容器以外之容器，其後面與車輛後保險桿後面間之水平距離應保持在三十公分以上。第130條另定突出零件之工作箱距離二十公分以上。第123條及第135條至第141條均已刪除。",
 "What horizontal clearance from the rear bumper is required for rear-discharge and other vehicle-mounted containers?",
 ["Rear-discharge main and shut-off valves at least 40 cm; other containers at least 30 cm at the rear","Rear-discharge main and shut-off valves at least 30 cm; other containers at least 40 cm at the rear","Rear-discharge main and shut-off valves at least 20 cm; other containers at least 50 cm at the rear","Rear-discharge main and shut-off valves at least 60 cm; other containers at least 20 cm at the rear"],
 "Articles 128 and 129; Articles 123 and 135 to 141 have been deleted."),

(HG,"第126條",2,"高壓氣體-運輸",
 "固定於車輛運輸之液化氣體灌氣容器等，應設何種設施？何者不在此限？",
 ["應設可防止容器內部液面搖動之防波板；符合國際規格之罐式集裝箱及無縫容器除外","應設可自動偵測液面高度之液面計；符合國際規格之罐式集裝箱及玻璃容器除外","應設可吸收運輸振動之避震座架；內容積在五千公升以下之容器及無縫容器除外","應設可遮蔽日照升溫之絕熱被覆；超低溫容器及低溫容器等絕熱型式容器除外"],"a",
 "第126條：固定於車輛運輸之液化氣體之灌氣容器等，應設可防止容器內部液面搖動之防波板；但符合國際規格之運輸用罐式集裝箱（ISOTank）及無縫容器不在此限。第132條並禁止液化可燃性氣體、液化毒性氣體或液化氧氣容器使用玻璃或其他易破損材料製造之液面計。",
 "What must vehicle-mounted liquefied gas cylinders be fitted with, and what is excluded?",
 ["Baffle plates preventing internal liquid surge; ISO tank containers and seamless containers are excluded","Level gauges automatically sensing liquid height; ISO tank containers and glass containers are excluded","Shock-absorbing mounts absorbing transport vibration; containers under 5,000 litres and seamless ones","Heat-insulating cladding shielding against sunlight; ultra-low and low-temperature containers excluded"],
 "Article 126; compare Article 132."),

(HG,"第127條",2,"高壓氣體-運輸",
 "固定於車輛運輸之容器，其頂部或突出物最高部超過該車輛最高點者，應設何種設施？",
 ["應設高度檢知桿","應設防波板裝置","應設緊急遮斷閥","應設輪擋固定器"],"a",
 "第127條：固定於車輛運輸之容器，其容器頂部或該容器設置之突出物最高部，超過該車輛最高點者，應設高度檢知桿。第130條另定容器原閥、緊急遮斷裝置之閥及其他主要零件突出者應收容於車輛左側以外之堅固工作箱內；第131條要求採取防止零件損傷致漏洩氣體之措施。",
 "What must be fitted when a vehicle-mounted container top or projection exceeds the vehicle high point?",
 ["A height detection pole must be fitted","A liquid surge baffle plate must be fitted","An emergency shut-off valve must be fitted","A wheel chock fixing device must be fitted"],
 "Article 127; compare Articles 130 and 131."),

(HG,"第130條",2,"高壓氣體-運輸",
 "容器之原閥、緊急遮斷裝置之閥及其他主要零件突出者，應如何收容？與後保險桿距離為何？",
 ["應收容於設置在車輛左側以外之堅固工作箱內；工作箱與後保險桿後面應保持二十公分以上","應收容於設置在車輛左側之堅固工作箱內；工作箱與後保險桿後面應保持四十公分以上","應收容於設置在車輛頂部之堅固工作箱內；工作箱與後保險桿後面應保持三十公分以上","應收容於設置在車輛底盤之堅固工作箱內；工作箱與後保險桿後面應保持十公分以上"],"a",
 "第130條：容器之原閥、緊急遮斷裝置之閥及其他主要零件突出者，應將此等零件收容於設置於車輛左側以外之堅固工作箱內，且使工作箱與車輛後保險桿後面間之水平距離保持在二十公分以上。第128條、第129條則分別定四十公分及三十公分之距離。",
 "How must projecting main valves and shut-off valves be housed, and what clearance from the rear bumper?",
 ["Housed in a strong tool box fitted other than on the vehicle left side; at least 20 cm from the rear bumper","Housed in a strong tool box fitted on the vehicle left side; at least 40 cm clearance from the rear bumper","Housed in a strong tool box fitted on the vehicle roof top; at least 30 cm clearance from the rear bumper","Housed in a strong tool box fitted on the vehicle chassis; at least 10 cm clearance from the rear bumper"],
 "Article 130; compare Articles 128 and 129."),

(HG,"第131條",2,"高壓氣體-運輸",
 "零件突出之容器，除收容於工作箱及保持距離外，尚應採取何種措施？",
 ["應採取防止因此等零件引起之損傷致漏洩氣體之措施","應採取防止因此等零件引起之靜電致發生火花之措施","應採取防止因此等零件遭受日照致溫度上升之措施","應採取防止因此等零件超過車寬致妨礙通行之措施"],"a",
 "第131條：零件突出之容器除依第128條至第130條規定外，應採取防止因此等零件引起之損傷致漏洩氣體之措施。第128條至第130條分別定後方卸出式容器四十公分、其他容器三十公分及工作箱二十公分之水平距離。",
 "Besides the tool box and clearances, what further measure is needed for containers with projecting parts?",
 ["Measures preventing gas leakage caused by damage arising from those projecting parts","Measures preventing sparks caused by static electricity arising from those projecting parts","Measures preventing temperature rise caused by sunlight falling on those projecting parts","Measures preventing obstruction to traffic caused by those parts exceeding vehicle width"],
 "Article 131, read with Articles 128 to 130."),

(HG,"第132條",2,"高壓氣體-運輸",
 "固定於車輛運輸之容器，內存液化可燃性氣體、液化毒性氣體或液化氧氣者，其液面計有何限制？",
 ["不得使用玻璃或其他易破損之材料製造之液面計","不得使用金屬或其他不透明之材料製造之液面計","不得使用浮球式或其他機械式構造之液面計裝置","不得使用電子式或其他需電源供應之液面計裝置"],"a",
 "第132條：固定於車輛運輸之容器，其容器內存液化可燃性氣體、液化毒性氣體或液化氧氣者，不得使用玻璃或其他易破損之材料製造之液面計。第51條對承液器及液化氣體儲槽亦定玻璃管液面計應有防止破損之措施，且氧氣或惰性氣體超低溫儲槽以外之儲槽以採用圓型玻璃管以外之液面計為限。",
 "What limit applies to level gauges on vehicle-mounted containers holding liquefied flammable, toxic or oxygen gas?",
 ["Level gauges made of glass or other easily broken materials may not be used","Level gauges made of metal or other non-transparent materials may not be used","Level gauges of float type or other mechanical construction may not be used","Level gauges of electronic type or requiring a power supply may not be used"],
 "Article 132; compare Article 51."),

(HG,"第133條",2,"高壓氣體-運輸",
 "固定於車輛運輸之容器，其閥或旋塞應採取何種措施？使用按鈕方式操作者又如何？",
 ["應採自外面易於識別開閉方向及開閉狀態之措施；按鈕方式者應在操作按鈕採辨識措施","應採自外面可上鎖並加鉛封之措施；按鈕方式者應由駕駛人隨身攜帶操作鑰匙保管","應採自外面可自動遮斷並記錄之措施；按鈕方式者應設置雙人操作之連鎖確認裝置","應採自外面可噴塗紅色警戒色之措施；按鈕方式者應於車輛左側設置防護柵與屏蔽"],"a",
 "第133條：固定於車輛運輸之容器，其容器之閥或旋塞，應採取自其外面易於識別開閉方向及開閉狀態之措施；但該閥或旋塞使用按鈕方式操作者，應在該操作按鈕採取辨識措施。第69條對製造設備之閥亦要求標示開閉方向與開閉狀況。",
 "What measure applies to valves or cocks on vehicle-mounted containers, and to button-operated ones?",
 ["Measures making open-close direction and status easily identified from outside; buttons must be marked too","Measures allowing locking and lead-sealing from outside; the driver must carry the operating key at all times","Measures allowing automatic shut-off and recording from outside; buttons need two-person interlock confirmation","Measures painting warning red colour visible from outside; button types need guard fences on the left side"],
 "Article 133; compare Article 69."),

(HG,"第134條",2,"高壓氣體-運輸",
 "以固定於車輛之容器運輸高壓氣體，於運輸之開始或終止時應如何辦理？",
 ["應檢點有否漏氣等之異常；發現異常時應即採取整修或防止危害之必要措施","應檢查駕駛人資格及行車紀錄器；發現不符時應即更換駕駛人並重新出車","應量測容器內壓力及溫度並登錄；發現超標時應即停車並通報消防機關到場","應清洗容器外部並確認標示完整；發現標示脫落時應即補貼並回廠重新檢查"],"a",
 "第134條：於運輸之開始或終止時，應檢點有否漏氣等之異常；發現異常時，應即採取整修或防止危害之必要措施。第125條並定固定於車輛運輸之灌氣容器等應經常保持其溫度於攝氏四十度以下，內存液化氣體者應設溫度計或可適當檢知溫度之計測裝置。",
 "What must be done at the start and end of transport by vehicle-mounted containers?",
 ["Check for leaks or other abnormality; if found, repair or take necessary measures to prevent harm at once","Check driver qualifications and the tachograph; if not compliant, change drivers and restart the journey","Measure and log internal pressure and temperature; if exceeded, stop and notify the fire authority at once","Wash the container exterior and confirm markings; if markings are lost, re-label and return for inspection"],
 "Article 134; compare Article 125."),

(HG,"第142條、第143條、第144條、第145條、第146條、第147條、第148條、第149條、第150條、第151條、第152條",2,"高壓氣體-運輸",
 "非固定於車輛之容器運輸高壓氣體時，灌氣容器等之溫度應保持在多少以下？",
 ["攝氏四十度以下；可計測氣體溫度之灌氣容器等，以該氣體之溫度為準","攝氏三十五度以下；可計測氣體溫度之灌氣容器等，以外氣溫度為準","攝氏五十度以下；可計測氣體溫度之灌氣容器等，以容器壁溫度為準","攝氏四十八度以下；可計測氣體溫度之灌氣容器等，以水槽溫度為準"],"a",
 "第143條：灌氣容器等應經常保持其溫度（可計測氣體溫度之灌氣容器等，為氣體之溫度）於攝氏四十度以下。第125條對固定於車輛運輸者、第79條第九款對容器放置場、第109條第三款對消費設備、第181條及第190條對消費作業均定攝氏四十度以下之相同標準。本節第142條及第144條至第152條均已刪除。",
 "For transport of containers not fixed on vehicles, at what temperature must filled cylinders be kept?",
 ["At or below 40 degrees Celsius; where gas temperature can be measured, that gas temperature governs","At or below 35 degrees Celsius; where gas temperature can be measured, the ambient temperature governs","At or below 50 degrees Celsius; where gas temperature can be measured, the wall temperature governs","At or below 48 degrees Celsius; where gas temperature can be measured, the bath temperature governs"],
 "Article 143; Articles 142 and 144 to 152 have been deleted."),

(HG,"第153條",1,"高壓氣體-運輸",
 "以導管運輸高壓氣體時，準用何項規定？",
 ["準用導管之設置規定，包括埋設深度、耐壓氣密試驗、厚度、防蝕及標示等","準用固定於車輛容器之運輸規定，包括防波板、高度檢知桿及工作箱距離","準用容器放置場之規定，包括警戒標示、輕質屋頂及四周二公尺禁煙火等","準用毒性氣體製造設備之規定，包括防毒措施、熔接接合及二重管構造等"],"a",
 "第153條：以導管運輸高壓氣體時，準用第80條之規定。第80條規定導管不得設置於有地塌山崩之虞場所、設於地盤上應距地面安裝並設標示、埋設於地盤下深度應距地面六十公分以上、應經常用壓力一．五倍以上耐壓試驗及常用壓力以上氣密試驗、厚度應能承受常用壓力二倍以上加壓、並應施予防蝕及吸收應力措施等。",
 "Which rules apply by reference when transporting high-pressure gas by pipeline?",
 ["The pipeline installation rules on burial depth, pressure and airtightness tests, thickness, anti-corrosion and marking","The rules for containers fixed on vehicles, covering baffle plates, height detection poles and tool box clearances","The cylinder yard rules, covering warning signs, light roofs and the ban on flames within two metres around","The toxic gas manufacturing rules, covering anti-poison measures, welded joints and double-pipe construction"],
 "Article 153, applying Article 80."),

(HG,"第154條",1,"高壓氣體-消費",
 "特定高壓氣體消費設施之事業場所，其境界與標示應如何設置？",
 ["應有明確之境界線，並於該場所外設置易於辨識之警戒標示","應設置高度二公尺以上之圍牆，並於內部設置避難方向指示標示","應以顏色區分消費區域，並於場所內部設置氣體種類之說明標示","應設置門禁管制系統，並於場所出入口設置人員識別之管制標示"],"a",
 "第154條：特定高壓氣體消費設施之事業場所應有明確之境界線，並於該場所外設置易於辨識之警戒標示。第31條對甲類製造事業單位固定式製造設備之事業場所有相同要求；第178條、第189條規定特定液化石油氣消費設備及可燃性氣體等之消費準用本條。",
 "How must the boundary and signage of premises with specified high-pressure gas consumption facilities be arranged?",
 ["A clear boundary line and an easily identified warning sign set outside the premises","A wall at least two metres high and evacuation direction signs set inside the premises","Colour-coded consumption zones and gas-type explanatory signs set inside the premises","An access control system and personnel identification signs set at the premises entrances"],
 "Article 154; compare Article 31."),

(HG,"第155條",2,"高壓氣體-消費",
 "設置可燃性氣體消費設備之廠房，其構造有何要求？",
 ["應具氣體自該設備漏洩時不致滯留之構造","應具可耐受氣體爆炸壓力之防爆牆構造","應具厚度九公分以上防護牆之區劃構造","應具可自動吸收漏洩氣體之除毒室構造"],"a",
 "第155條：設置可燃性氣體消費設備之廠房，應具氣體自該設備漏洩時不致滯留之構造。第38條對設置可燃性氣體製造設備或冷媒設備壓縮機等之廠房亦定不得因氣體漏洩致滯留於廠內之構造；第167條並定消費設備有漏洩積滯之虞場所應設氣體漏洩檢知警報設備，但液氧除外。",
 "What structural requirement applies to buildings housing flammable gas consumption equipment?",
 ["A structure preventing gas leaking from the equipment from accumulating","A blast wall structure able to withstand the pressure of a gas explosion","A partitioned structure using protective walls at least nine centimetres","A detox room structure automatically absorbing any gas that has leaked"],
 "Article 155; compare Articles 38 and 167."),

(HG,"第156條",1,"高壓氣體-消費",
 "特定高壓氣體消費設備之材料，應如何選用？",
 ["應使用足以適應該氣體種類、性狀、溫度及壓力等諸性質要求者","應一律使用經超音波探傷檢查合格之低溫用高強度合金鋼材料","應使用中央主管機關指定之標準材料，並全面禁止使用非金屬","應使用可承受常用壓力五倍以上厚度且經放射線檢查合格者"],"a",
 "第156條：特定高壓氣體消費設備之材料，應使用足以適應該氣體之種類、性狀、溫度及壓力等諸性質之要求者。第44條對氣體設備之材料有完全相同之要求；第158條、第159條則另定儲存相關設備之耐壓氣密試驗及厚度規定。",
 "How must materials for specified high-pressure gas consumption equipment be selected?",
 ["They must suit the kind, properties, temperature and pressure of the gas concerned","They must all be low-temperature high-strength alloy steel passing ultrasonic testing","They must be standard materials designated by the authority, banning all non-metals","They must be five times the working pressure in thickness and pass radiographic tests"],
 "Article 156; identical to Article 44."),

(HG,"第157條",2,"高壓氣體-消費",
 "消費設備之基礎，對於一定規模以上儲槽之支柱有何規定？",
 ["儲存能力在一百立方公尺或一公噸以上之儲槽支柱，應置於同一基礎並緊密結合","儲存能力在三百立方公尺或三公噸以上之儲槽支柱，應分置不同基礎以分散載重","儲存能力在一千立方公尺或十公噸以上之儲槽支柱，應埋設於地盤內並填足乾砂","儲存能力在五百立方公尺或五公噸以上之儲槽支柱，應以防液堤圍繞並緊密結合"],"a",
 "第157條：消費設備（除配管之基礎外）不得有不均勻沈陷致使該設備發生有害之變形；儲存能力在一百立方公尺或一公噸以上之儲槽之支柱（未置支柱之儲槽者為其底座）應置於同一基礎，並緊密結合。第45條對製造設備有相同規定；第174條並要求儲槽應隨時注意有無沈陷現象。",
 "What foundation rule applies to supports of larger tanks in consumption equipment?",
 ["Supports of tanks of 100 cubic metres or 1 tonne capacity must sit on one foundation, tightly joined","Supports of tanks of 300 cubic metres or 3 tonnes capacity must sit on separate foundations to spread load","Supports of tanks of 1,000 cubic metres or 10 tonnes capacity must be buried and packed with dry sand","Supports of tanks of 500 cubic metres or 5 tonnes capacity must be surrounded by a dike and tightly joined"],
 "Article 157; identical in substance to Article 45."),

(HG,"第158條",3,"高壓氣體-消費",
 "消費設備之儲存相關設備應經何種試驗合格？其中液氯儲存設備之適用範圍為何？",
 ["常用壓力一．五倍以上耐壓試驗及常用壓力以上氣密試驗；液氯以一千公斤以上未滿三千公斤為限","常用壓力二倍以上耐壓試驗及常用壓力一．五倍以上氣密試驗；液氯以三千公斤以上者為限","最高使用壓力三倍以上耐壓試驗及最高使用壓力以上氣密試驗；液氯以五百公斤以上者為限","設計壓力一．二倍以上耐壓試驗及設計壓力以上之氣密試驗；液氯以一萬公斤以上者為限"],"a",
 "第158條：消費設備之儲存設備、導管、減壓設備及此等設備之配管等（儲存相關設備，但容器除外；且液氯儲存設備以儲存能力在一千公斤以上未滿三千公斤者為限）應經以常用壓力一．五倍以上壓力實施之耐壓試驗及以常用壓力以上壓力實施之氣密試驗或具有同等以上效力之試驗合格者。第28條並定液氯一千公斤以上為特定高壓氣體消費事業單位門檻。",
 "What tests must storage-related consumption equipment pass, and what liquid chlorine range applies?",
 ["Hydrostatic at 1.5 times working pressure and airtightness at working pressure; liquid chlorine 1,000 to under 3,000 kg","Hydrostatic at twice working pressure and airtightness at 1.5 times working pressure; liquid chlorine 3,000 kg or more","Hydrostatic at three times maximum pressure and airtightness at maximum pressure; liquid chlorine 500 kg or more","Hydrostatic at 1.2 times design pressure and airtightness at design pressure; liquid chlorine 10,000 kg or more"],
 "Article 158; compare Article 28."),

(HG,"第159條",2,"高壓氣體-消費",
 "儲存相關設備之厚度應符合何項要求？",
 ["應具有以常用壓力二倍以上之壓力加壓時，不致引起降伏變形之厚度","應具有以常用壓力一．五倍以上之壓力加壓時，不致產生龜裂之厚度","應具有以最高使用壓力三倍以上之壓力加壓時，不致發生破裂之厚度","應具有以設計壓力一．二倍以上之壓力加壓時，不致發生變形之厚度"],"a",
 "第159條：儲存相關設備應具有以常用壓力二倍以上之壓力加壓時，不致引起降伏變形之厚度或經中央主管機關認定具有同等以上強度者。第43條對高壓氣體設備、第80條第六款對導管亦有相同之常用壓力二倍規定。",
 "What thickness requirement applies to storage-related consumption equipment?",
 ["A thickness that will not yield when pressurised to at least twice the normal working pressure","A thickness that will not crack when pressurised to at least 1.5 times the working pressure","A thickness that will not rupture when pressurised to at least three times the maximum pressure","A thickness that will not deform when pressurised to at least 1.2 times the design pressure"],
 "Article 159; the same rule appears in Articles 43 and 80."),

(HG,"第160條",2,"高壓氣體-消費",
 "儲存相關設備應設置何種計器及安全裝置？何者不適用？",
 ["應設適當壓力表及可使壓力恢復至最高使用壓力以下之安全裝置；壓縮氣體之減壓設備除外","應設適當溫度計及可使溫度下降至常用溫度以下之冷卻裝置；液化氣體之儲存設備除外","應設適當液面計及可自動停止灌裝之遮斷裝置；毒性氣體之消費設備除外","應設適當流量計及可自動關閉之緊急遮斷閥；可燃性氣體之導管設備除外"],"a",
 "第160條：儲存相關設備（不含壓縮氣體之減壓設備）應設置適當之壓力表，且應置該設備內壓力超過最高使用壓力時可迅使其壓力恢復至最高使用壓力以下之安全裝置。第48條對高壓氣體設備、儲存設備或冷媒設備有相同規定。",
 "What gauge and safety device must storage-related consumption equipment have, and what is excluded?",
 ["A suitable pressure gauge and a safety device restoring pressure below the maximum; compressed-gas reducers excluded","A suitable thermometer and a cooling device restoring temperature below the normal level; liquefied gas tanks excluded","A suitable level gauge and a shut-off device stopping filling automatically; toxic gas consumption equipment excluded","A suitable flow meter and an emergency shut-off valve closing automatically; flammable gas pipelines are excluded"],
 "Article 160; compare Article 48."),

(HG,"第161條",2,"高壓氣體-消費",
 "液氨或液氯之減壓設備與該氣體進行之反應、燃燒設備間之配管，應設何種裝置？",
 ["應設逆流防止裝置","應設緊急遮斷裝置","應設氣體漏洩警報","應設二重管之構造"],"a",
 "第161條：液氨或液氯之減壓設備與該氣體進行之反應、燃燒設備間之配管，應設逆流防止裝置。第183條對環氧乙烷之消費亦定應於事前以氮氣或二氧化碳置換設備內部之氣體，且在環氧乙烷容器與消費設備間之配管設逆流防止裝置。",
 "What device must be fitted in the piping between liquid ammonia or chlorine reducers and the reaction or combustion equipment?",
 ["A backflow prevention device must be fitted","An emergency shut-off device must be fitted","A gas leakage detection alarm must be fitted","A double-pipe construction must be provided"],
 "Article 161; compare Article 183."),

(HG,"第162條",2,"高壓氣體-消費",
 "消費設施之可燃性氣體低溫儲槽，應有何種設施？",
 ["應有防止其內壓降低至較外壓為低時，不致使該儲槽發生破裂之設施","應有防止其內壓上升超過最高使用壓力時，不致使該儲槽爆炸之設施","應有防止其液面搖動致使槽壁受衝擊時，不致使該儲槽變形之設施","應有防止其溫度上升超過攝氏四十度時，不致使該儲槽膨出之設施"],"a",
 "第162條：可燃性氣體低溫儲槽，應有防止其內壓降低至較外壓為低時不致使該儲槽發生破裂之設施。第50條對製造設施之可燃性氣體低溫儲槽有相同規定；第13條並定可燃性氣體低溫儲槽之定義。",
 "What facility must a low-temperature flammable-gas tank in a consumption facility have?",
 ["Facilities preventing rupture when internal pressure falls below the external pressure","Facilities preventing explosion when internal pressure exceeds the maximum pressure","Facilities preventing deformation when liquid surge impacts the wall of the tank","Facilities preventing bulging when the temperature rises above forty degrees Celsius"],
 "Article 162; identical to Article 50."),

(HG,"第163條",2,"高壓氣體-消費",
 "液氨或液氯之消費設備，應設置氣體漏洩時之除毒措施，其內容為何？",
 ["防止漏洩氣體擴散之裝置、依氣體毒性選擇吸收設備及吸收劑、防毒面罩保管於安全場所","以水噴霧稀釋漏洩氣體、設置排放於大氣之釋放管、防毒面罩由勞工自行保管備用","設置防液堤及乾砂填充層、以惰性氣體置換設備內部、防毒面罩置於作業現場入口","設置厚度十二公分防護牆、以撒水裝置降溫、防毒面罩由承攬人負責維護及保管"],"a",
 "第163條：液氨或液氯之消費設備應依下列規定設置氣體漏洩時之除毒措施：一、可適當防止漏洩氣體擴散之裝置。二、應依該氣體毒性、氣體種類、數量及消費狀況，選擇吸收各該氣體之設備及吸收劑。三、除毒使用之防毒面罩及其他防護具，應保管於安全場所，並經常維護於良好狀態。第61條對毒性氣體製造設備有相同架構之規定。",
 "What detoxification measures must liquid ammonia or chlorine consumption equipment provide?",
 ["Devices preventing diffusion, absorbers and absorbents matched to the gas, and masks kept safely maintained","Water spray dilution of leaked gas, a relief pipe discharging to air, and masks kept by each worker himself","A dike with dry sand fill, inert gas purging of the equipment, and masks placed at the worksite entrance","A protective wall twelve centimetres thick, sprinkler cooling, and masks maintained by the contractor"],
 "Article 163; compare Article 61."),

(HG,"第164條",2,"高壓氣體-消費",
 "液氨或液氯之消費設備之配管、管接頭及閥之接合，應採用何種方式？",
 ["應採用熔接接合；不適於熔接接合者，得以安全上具必要強度之凸緣接合代替","應採用螺紋接合；不適於螺紋接合者，得以安全上具必要強度之熔接接合代替","應採用套管接合；不適於套管接合者，得以安全上具必要強度之壓接接合代替","應採用可撓管接合；不適於可撓接合者，得以安全上具必要強度之管帶鎖緊代替"],"a",
 "第164條：液氨或液氯之消費設備之配管、管接頭及閥之接合，應採用熔接接合；但不適於熔接接合者，得以安全上具有必要強度之凸緣接合代替。第64條對毒性氣體之氣體設備配管有完全相同之規定；第165條並定必要處所應採二重管構造。",
 "How must piping, joints and valves of liquid ammonia or chlorine consumption equipment be connected?",
 ["By welded joints; where welding is unsuitable, flange joints of the necessary strength may be used","By threaded joints; where threading is unsuitable, welded joints of the necessary strength may be used","By sleeve joints; where sleeving is unsuitable, crimped joints of the necessary strength may be used","By flexible hose joints; where unsuitable, tightening with hose clamps of necessary strength may be used"],
 "Article 164; identical to Article 64."),

(HG,"第165條",2,"高壓氣體-消費",
 "液氨或液氯之消費設備之配管，在必要處所應採用何種構造？",
 ["應依氣體種類、性狀、壓力及配管鄰近狀況，在必要處所採用二重管構造","應依氣體種類、性狀、壓力及配管鄰近狀況，在必要處所採用可撓管構造","應依氣體種類、性狀、壓力及配管鄰近狀況，在必要處所採用地下埋設構造","應依氣體種類、性狀、壓力及配管鄰近狀況，在必要處所採用玻璃襯裡構造"],"a",
 "第165條：液氨或液氯之消費設備之配管，應依各該氣體之種類、性狀、壓力及該配管鄰近狀況，在必要處所採用二重管構造。第65條對毒性氣體之氣體設備配管有完全相同之規定；第164條則定應採熔接接合。",
 "What piping construction is required at necessary points for liquid ammonia or chlorine consumption equipment?",
 ["Double-pipe construction according to the gas type, properties, pressure and surroundings","Flexible-hose construction according to the gas type, properties, pressure and surroundings","Underground buried construction according to the gas type, properties, pressure and location","Glass-lined construction according to the gas type, properties, pressure and surroundings"],
 "Article 165; identical to Article 65."),

(HG,"第166條",1,"高壓氣體-消費",
 "可燃性氣體之消費設備，對靜電應採取何種措施？",
 ["應採取可除卻該設備產生之靜電之措施","應採取可承受該設備爆炸壓力之防爆牆","應採取可探測該設備漏洩氣體之警報器","應採取可降低該設備表面溫度之撒水器"],"a",
 "第166條：可燃性氣體之消費設備，應採取可除卻該設備產生之靜電之措施。第66條對可燃性氣體製造設備有相同規定；第92條第五款、第93條第七款對移動式製造設備之灌裝亦要求除卻靜電。",
 "What must be done about static electricity in flammable gas consumption equipment?",
 ["Measures capable of eliminating static electricity generated by the equipment","Blast walls capable of withstanding an explosion pressure of the equipment","Alarm detectors capable of sensing gas leaking from the equipment concerned","Sprinklers capable of lowering the surface temperature of the equipment"],
 "Article 166; identical to Article 66."),

(HG,"第167條",2,"高壓氣體-消費",
 "消費設備中有氣體漏洩致積滯之虞之場所，應設置何種設備？何種氣體除外？",
 ["應設可探測漏洩氣體且自動發出警報之氣體漏洩檢知警報設備；但液氧除外","應設可吸收漏洩氣體且自動中和之除毒設備及吸收劑儲槽；但液氨除外","應設可稀釋漏洩氣體且自動送風之整體換氣裝置與排氣設備；但液氯除外","應設可遮斷漏洩氣體且自動停止之緊急遮斷裝置及逆止閥；但氫氣除外"],"a",
 "第167條：消費設備中有氣體漏洩致積滯之虞之場所，應設置可探測該漏洩氣體，且自動發出警報之氣體漏洩檢知警報設備，但液氧除外。第60條對可燃性氣體或毒性氣體之製造設備亦有相同規定；第178條規定特定液化石油氣消費設備準用本條。",
 "What must be installed where leaked gas may accumulate in consumption equipment, and what gas is excluded?",
 ["A gas leak detection alarm detecting the gas and sounding automatically; liquid oxygen is excluded","A detoxification unit with absorbent tanks absorbing and neutralising the gas; liquid ammonia excluded","General ventilation and exhaust equipment diluting the leaked gas with air; liquid chlorine excluded","An emergency shut-off device with check valve cutting off the gas supply; hydrogen gas is excluded"],
 "Article 167; compare Article 60."),

(HG,"第168條",2,"高壓氣體-消費",
 "哪些特定高壓氣體之消費設備，應依消防法有關規定設置必要之消防設備？",
 ["壓縮氫氣、壓縮天然氣、液氧及液氨之消費設備","液氯、液氨、氰化氫及光氣之毒性氣體消費設備","液化石油氣、環丙烷、甲胺及二甲醚之消費設備","二氧化碳、氮氣、氬氣及氦氣之惰性氣體消費設備"],"a",
 "第168條：壓縮氫氣、壓縮天然氣、液氧及液氨之消費設備，應依消防法有關規定設置必要之消防設備。第177條並定特定液化石油氣消費設備應依消防法設必要之消防設備；第67條、第91條對製造設備亦有相同規定。第3條所列特定高壓氣體尚包括液氯及液化石油氣。",
 "Which specified high-pressure gas consumption equipment must have fire equipment under the Fire Services Act?",
 ["Consumption equipment for compressed hydrogen, compressed natural gas, liquid oxygen and ammonia","Consumption equipment for toxic gases such as chlorine, ammonia, hydrogen cyanide and phosgene","Consumption equipment for LPG, cyclopropane, methylamine and dimethyl ether and their mixtures","Consumption equipment for inert gases such as carbon dioxide, nitrogen, argon and helium gases"],
 "Article 168; compare Articles 67, 91 and 177."),

(HG,"第170條、第171條",2,"高壓氣體-消費",
 "供消費液氧使用之閥及器具，應於事前如何處理？",
 ["應於事前除卻石油類、油脂類及可燃性物質","應於事前以氮氣或二氧化碳置換內部氣體","應於事前實施音響檢查及容器內部之檢查","應於事前以熱濕布或溫水加熱至常用溫度"],"a",
 "第170條：供消費液氧使用之閥及器具，應於事前除卻石油類、油脂類及可燃性物質。第185條對氧氣之消費、第214條對氧氣之廢棄、第97條第二款對灌注氧氣於容器均有相同之除卻石油類油脂類要求。第171條已刪除。",
 "How must valves and appliances used for consuming liquid oxygen be treated beforehand?",
 ["Petroleum products, oils and fats and combustible substances must be removed first","The internal gas must first be replaced with nitrogen or with carbon dioxide gas","A sound inspection and an internal inspection of the container must be done first","They must first be warmed to normal temperature with hot wet cloth or warm water"],
 "Article 170 (Article 171 has been deleted); compare Articles 185 and 214."),

(HG,"第172條",2,"高壓氣體-消費",
 "設置於消費設備之閥或旋塞及其開閉按鈕，應準用何項規定？",
 ["準用製造設備閥之標示、加鎖鉛封及設置作業台等可使作業人員適當操作之措施","準用固定於車輛容器之閥應自外面易於識別開閉方向及開閉狀態之相關規定","準用安全閥應調整於最高使用壓力以下吹洩並於檢查後固定設定壓力之規定","準用毒性氣體配管應採熔接接合並於必要處所採二重管構造之相關各項規定"],"a",
 "第172條：設置於消費設備之閥或旋塞及以按鈕方式等操作該閥或旋塞之開閉按鈕等，準用第69條之規定採取可使作業人員適當操作該閥或旋塞之措施。第69條包括開閉方向與開閉狀況標示、配管標示流體種類與流動方向、加鎖鉛封及設置作業台等四款規定。",
 "Which rules apply by reference to valves, cocks and their buttons on consumption equipment?",
 ["The manufacturing equipment rules on marking, locking or lead sealing and providing a work platform","The rules for vehicle-mounted containers on identifying open-close direction and status from outside","The rules requiring safety valves to blow at or below maximum pressure with fixed settings after test","The rules requiring toxic gas piping to be welded and to use double-pipe construction where needed"],
 "Article 172, applying Article 69."),

(HG,"第173條",2,"高壓氣體-消費",
 "從事消費設備之修理、清掃等作業，應準用何項規定？",
 ["準用訂定作業計畫、指定作業負責人、置換內部氣體、設盲板阻隔及懸掛禁止操作標示牌等","準用實施耐壓試驗與氣密試驗合格、並具常用壓力二倍加壓不降伏變形厚度等規定","準用設置氣體漏洩檢知警報設備、除毒設備及選擇適當吸收劑等相關之各項規定","準用容器放置場之警戒標示、輕質屋頂、分區放置及四周二公尺禁煙火等規定"],"a",
 "第173條：從事消費設備之修理等相關作業，準用第75條之規定。第75條要求事前訂定作業計畫並指定作業負責人於其監督下實施、以不易反應之氣體或液體置換內部氣體、必要時再以空氣置換、開放部分前後之閥及旋塞關閉並設盲板阻隔、懸掛禁止操作標示牌並加鎖、作業終了未確認可安全正常動作前不得供製造使用。",
 "Which rules apply by reference to repair and cleaning of consumption equipment?",
 ["Rules on work plans, a designated person in charge, purging, blind plates and do-not-operate tags with locks","Rules on passing hydrostatic and airtightness tests and on thickness withstanding twice the working pressure","Rules on installing gas leak detection alarms, detoxification equipment and selecting suitable absorbents","Rules on cylinder yard warning signs, light roofs, separate placement and no flames within two metres"],
 "Article 173, applying Article 75."),

(HG,"第174條",1,"高壓氣體-消費",
 "消費設施之儲槽，對沈陷現象應如何處理？",
 ["應隨時注意有無沈陷現象，如有沉陷應視其程度採取適當因應措施","應每三個月測量沈陷量一次，如有沉陷應立即停止使用並拆除重建","應於設置時測量基準點即可，其後沈陷情形由目的事業主管機關認定","應以防液堤圍繞並填足乾砂，如有沉陷應增加乾砂厚度至一公尺以上"],"a",
 "第174條：儲槽應隨時注意有無沈陷現象，如有沉陷現象時，應視其沉陷程度採取適當因應措施。第76條對製造事業單位儲存能力一百立方公尺或一公噸以上之儲槽、第113條第五款對以儲槽儲存高壓氣體者均有相同規定；第157條並定儲槽支柱應置於同一基礎並緊密結合。",
 "How must settlement of tanks in consumption facilities be handled?",
 ["Watch for settlement at all times and take suitable measures matched to the degree of settlement","Measure settlement every three months and, if found, stop use immediately and rebuild the tank","Measure the datum point at installation only, later settlement being judged by the sector authority","Surround with a dike packed with dry sand and, if settlement occurs, increase the sand to one metre"],
 "Article 174; compare Articles 76 and 113."),

(HG,"第175條",2,"高壓氣體-消費",
 "操作消費設備之閥時，應考慮何事項？該事項應如何落實？",
 ["應考慮閥之材料、構造及使用狀況，防止過巨之力加諸於閥上，並訂入工作守則中","應考慮閥之製造廠牌及價格，防止使用非原廠零件，並報請勞動檢查機構核備","應考慮閥之開啟次數及年限，每屆滿三年即予汰換，並將紀錄保存五年備查","應考慮閥之顏色及編號，由二人以上共同操作，並全程錄影存證備供查核"],"a",
 "第175條：操作消費設備之閥時，應考慮該閥之材料、構造及使用狀況，採取必要之措施以防止過巨之力加諸於閥上，並訂入工作守則中。第77條對製造設備之閥有相同規定；第179條規定操作可燃性氣體、毒性氣體及氧氣之灌氣容器等之閥準用本條；第216條對廢棄時灌氣容器等之閥類亦準用本條。",
 "What must be considered when operating valves on consumption equipment, and how is it implemented?",
 ["The valve material, construction and condition, avoiding excessive force, written into the work rules","The valve brand and price, avoiding non-original parts, and reported to the labour inspection agency","The number of operations and service life, replacing every three years, with records kept five years","The valve colour and number, operated by two persons together, with the whole process video recorded"],
 "Article 175; compare Articles 77, 179 and 216."),

(HG,"第176條",3,"高壓氣體-液化石油氣",
 "自特定液化石油氣消費設備之儲存相關設備外面至處理煙火之設備，應保持多少距離？",
 ["應保持八公尺以上距離，或設置防止漏洩氣體流竄至煙火設備之措施","應保持五公尺以上距離，或設置防止漏洩氣體流竄至煙火設備之措施","應保持十二公尺以上距離，或設置防止漏洩氣體流竄至煙火設備措施","應保持二十公尺以上距離，或設置防止漏洩氣體流竄至煙火設備措施"],"a",
 "第176條：自特定液化石油氣消費設備之儲存設備、導管、減壓設備及此等設備之配管外面至處理煙火（不含消費設備內使用之煙火）之設備應保持八公尺以上距離，或在該儲存相關設備與處理煙火之設備間設置防止氣體自該設備漏洩時不致使其流竄至煙火設備之措施。第33條對可燃性氣體製造設備亦定八公尺以上。",
 "What distance must be kept from specified LPG consumption storage equipment to fire-handling equipment?",
 ["At least 8 metres, or measures preventing leaked gas from drifting to the fire equipment","At least 5 metres, or measures preventing leaked gas from drifting to the fire equipment","At least 12 metres, or measures preventing leaked gas from drifting to fire equipment","At least 20 metres, or measures preventing leaked gas from drifting to fire equipment"],
 "Article 176; compare Article 33."),

(HG,"第177條",1,"高壓氣體-液化石油氣",
 "特定液化石油氣消費設備，應依何規定設置消防設備？",
 ["應依消防法有關規定設置必要之消防設備","應依建築技術規則設置必要之滅火器具","應依職業安全衛生設施規則設置滅火器","應依危險物品管理辦法設置泡沫滅火設施"],"a",
 "第177條：特定消費設備，應依消防法有關規定設置必要之消防設備。第168條對壓縮氫氣、壓縮天然氣、液氧及液氨之消費設備亦有相同規定；第67條、第91條則對製造設備定應依消防法設消防或滅火設備。",
 "Under what law must fire equipment be provided for specified LPG consumption equipment?",
 ["Under the relevant provisions of the Fire Services Act","Under the Building Technical Regulations for extinguishers","Under the Occupational Safety and Health Facilities Rules","Under the Regulations on Management of Dangerous Goods"],
 "Article 177; compare Articles 67, 91 and 168."),

(HG,"第178條",3,"高壓氣體-液化石油氣",
 "特定液化石油氣消費設備，除距離八公尺及消防設備規定外，下列何者屬其準用之規定？",
 ["境界警戒標示、材料選用、耐壓氣密試驗、壓力表安全裝置、漏洩警報及儲存設備五公尺禁煙火","毒性氣體之除毒措施、配管熔接接合、二重管構造及逆流防止裝置等相關之各項規定","冷凍設備壓縮機設置限制、冷媒設備氣密與耐壓試驗及承液器液面計等相關規定","固定於車輛容器之防波板、高度檢知桿、工作箱距離及運輸開始終止檢點等規定"],"a",
 "第178條：特定消費設備除依第176條、第177條規定外，準用第154條至第160條、第162條、第167條、第169條及第172條至第175條之規定，包括境界警戒標示、廠房不滯留構造、材料、基礎、耐壓與氣密試驗、厚度、壓力表與安全裝置、低溫儲槽防破裂、漏洩警報、儲存相關設備四周五公尺禁煙火、閥操作、修理作業、沈陷注意等。第163條至第165條之液氨液氯規定則未列入。",
 "Besides the eight-metre distance and fire equipment, which rules apply to specified LPG consumption equipment?",
 ["Boundary signs, materials, pressure tests, gauges and safety devices, leak alarms and the five-metre no-flame rule","Detoxification measures for toxic gases, welded piping joints, double-pipe construction and backflow prevention","Siting limits for refrigeration compressors, airtightness and pressure tests of refrigerant units and level gauges","Baffle plates, height detection poles, tool box clearances and start and end of transport checks for vehicles"],
 "Article 178 lists the provisions applied by reference."),
]
